def comps_wrap(g,val=0,H=None,W=None):
    if H is None: H,W=g.shape
    g=np.array(g); seen=np.zeros_like(g,bool); out=[]
    for r in range(H):
        for c in range(W):
            if g[r,c]==val and not seen[r,c]:
                st=[(r,c)]; seen[r,c]=True; comp=[]
                while st:
                    y,x=st.pop(); comp.append((y,x))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and not seen[ny,nx] and g[ny,nx]==val:
                                seen[ny,nx]=True; st.append((ny,nx))
